            if (deposits[i][j] == 1) {
                if (i > 0) {
                    deposits[i - 1][j] = Math.max(deposits[i - 1][j], deposits[i][j]);
                }
                if (j > 0) {
                    deposits[i][j - 1] = Math.max(deposits[i][j - 1], deposits[i][j]);
                }
                if (i < grid.length - 1) {
                    deposits[i + 1][j] = Math.max(deposits[i + 1][j], deposits[i][j]);
                }
                if (j < grid[0].length - 1) {
                    deposits[i][j + 1] = Math.max(deposits[i][j + 1], deposits[i][j]);
