public static int countOilDeposits(char[][] grid) {
    int nrOfDeposits = 0;
    int rows = grid.length;
    int cols = grid[0].length;
    boolean[][] visited = new boolean[rows][cols];

    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            if (grid[i][j] == '@' && !visited[i][j]) {
                nrOfDeposits++;
                exploreNeighborhood(grid, visited, i, j);
            }
        }
    }

    return nrOfDeposits;
}

private static void exploreNeighborhood(char[][] grid, boolean[][] visited, int row, int col) {
    if (row < 0 || row >= grid.length || col < 0 || col >= grid[0].length || grid[row][col] != '@' || visited[row][col]) {
        return;
    }

    visited[row][col] = true;

    exploreNeighborhood(grid, visited, row - 1, col);
    exploreNeighborhood(grid, visited, row, col - 1);
    exploreNeighborhood(grid, visited, row, col + 1);
    exploreNeighborhood(grid, visited, row + 1, col);
}
```
