            // If the destination node has not been visited, mark it as visited and enqueue it
            if (!visited[edge[1]]) {
                visited[edge[1]] = true;
                queue.add(edge[1]);
            }
        }
    }

    // If not all nodes have been visited, return -1
    for (int i = 0; i < n; i++) {
        if (!visited[i]) {
            return -1;
        }
    }

    // Return the minimum time required to collect all apples and return to node 0
    return minTime;
