public static int maxSubarraySum(int[] array, int k) {
    if (array.length < k) return 0;
    int[] prefix = new int[array.length + 1];
    for (int i = 1; i < array.length; i++) {
        prefix[i] = Math.max(prefix[i - 1], prefix[i - 1] + array[i]);
    }
    int max = 0;
    for (int i = 0; i < array.length - k + 1; i++) {
