public String sortString(String s) {
    char[] chars = s.toCharArray();
    Arrays.sort(chars);
    StringBuilder sb = new StringBuilder();
    while (chars.length > 0) {
        // Pick the smallest character
        char smallest = chars[0];
        sb.append(smallest);
        // Remove the smallest character
        chars = Arrays.copyOfRange(chars, 1, chars.length);
        // Pick the smallest character that is greater than the last appended character
        smallest = findNextSmallest(chars, smallest);
        while (smallest != '\u0000') {
            sb.append(smallest);
            chars = Arrays.copyOfRange(chars, 1, chars.length);
            smallest = findNextSmallest(chars, smallest);
        }

        // Pick the largest character
        char largest = chars[chars.length - 1];
        sb.append(largest);
        // Remove the largest character
        chars = Arrays.copyOfRange(chars, 0, chars.length - 1);
        // Pick the largest character that is smaller than the last appended character
        largest = findNextLargest(chars, largest);
        while (largest != '\u0000') {
            sb.append(largest);
            chars = Arrays.copyOfRange(chars, 1, chars.length);
            largest = findNextLargest(chars, largest);
        }
    }
    return sb.toString();
}

private char findNextSmallest(char[] chars, char smallest) {
    for (char c : chars) {
        if (c < smallest && c > sb.charAt(sb.length() - 1)) {
