public int minOperations(int n) {
    int[] arr = new int[n];
    for (int i = 0; i < n; i++) {
        arr[i] = (2 * i) + 1;
    }
    int operations = 0;
    while (!checkIfEqual(arr)) {
        int maxDiff = Integer.MIN_VALUE;
        int x = -1, y = -1;
        for (int i = 0; i < n - 1; i++) {
            for (int j = i + 1; j < n; j++) {
                int diff = Math.abs(arr[i] - arr[j]);
                if (diff > maxDiff) {
                    maxDiff = diff;
                    x = i;
                    y = j;
                }
            }
        }
        arr[x] -= 1;
        arr[y] += 1;
        operations++;
    }
    return operations;
}

private boolean checkIfEqual(int[] arr) {
    int target = arr[0];
    for (int i = 1; i < arr.length; i++) {
        if (arr[i] != target) {
            return false;
        }
    }
    return true;
}
