    int n = s.length();
    int[] length = new int[n + 1];
    int[] count = new int[n];
    int[] res = new int[n + 1];

    for (int i = 1; i <= n; i++) {
        length[i] = i;
        count[i - 1] = 1;
        for (int j = 0; j < i - 1; j++) {
            if (s.charAt(j) == s.charAt(i - 1)) {
