import java.util.Optional;

public class Range {

    private final int start;
    private final int end;

    private Range(int start, int end) {
        this.start = start;
        this.end = end;
    }

    public static Range from(int start, int end) {
        return new Range(start, end);
    }

    public static Range singleValue(int value) {
        return new Range(value, value);
    }

    public boolean contains(int value) {
        return start <= value && value < end;
    }

    public boolean overlaps(Range other) {
        return contains(other.start) || contains(other.end) || other.contains(start);
    }

    public Optional<Range> intersection(Range other) {
        int min = Math.max(start, other.start);
        int max = Math.min(end, other.end);
        if (min <= max) {
            return Optional.of(new Range(min, max));
        }
        return Optional.empty();
    }

    public void print() {
        if (start == end) {
            System.out.println("single value: " + start);
        } else {
            System.out.println("range: [" + start + ", " + end + ")");
        }
    }
}
