private static int dfs(int[][] mat, int i, int j) {
    int m = mat.length;
    int n = mat[0].length;
    int count = 1;

    if (i < 0 || i >= m || j < 0 || j >= n || mat[i][j] == 0) {
        return count;
    }

    mat[i][j] = 0;
    count++;
    count = Math.max(count, dfs(mat, i + 1, j));
    count = Math.max(count, dfs(mat, i, j + 1));
    count = Math.max(count, dfs(mat, i - 1, j));
    count = Math.max(count, dfs(mat, i, j - 1));

    return count;
}
