        int m = mat.length;
        int n = mat[0].length;
        for (int i = 0; i < m + n - 1; i++) {
            if (i < m) {
                for (int j = 0; j < m - i; j++) {
                    result.add(mat[i + j][j]);
                }
            }
            if (i < n) {
                for (int j = 1; j < n - i; j++) {
                    result.add(mat[m - j][i + j]);
