        for (int j = 0; j < n; j++) {
            if (i == j) {
                result[idx++] = mat[i][j];
            } else if (i > j) {
                result[idx++] = mat[i][j];
            } else {
                result[idx++] = mat[j][i];
            }
        }
    }
    return result;
