// Function to find the next permutation of a given array
public static boolean next_permutation(char[] digits) {
    int i = digits.length - 2;
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }
    if (i == -1) {
        return false;
    }
    int j = digits.length - 1;
    while (digits[j] <= digits[i]) {
        j--;
    }
    swap(digits, i, j);
    reverse(digits, i + 1);
    return true;
}

// Function to swap two elements of an array
private static void swap(char[] digits, int i, int j) {
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;
}

// Function to reverse an array
private static void reverse(char[] digits, int start) {
    int i = start, j = digits.length - 1;
    while (i < j) {
        swap(digits, i, j);
        i++;
        j--;
    }
}
